<include file="Public:header"/><link rel="stylesheet" type="text/css" href="/tpl/System/Static/css/style.css" /><link rel="stylesheet" href="{pigcms{$static_path}css/bootstrap.min.css"><link rel="stylesheet" href="{pigcms{$static_path}css/ace.min.css" id="main-ace-style">	<div class="mainbox">		<div style="margin-left: 10px;color: #9a9999">			<span> 说明：</span>			<p>1.先设置排序再关联店铺，否则排序无效</p>		</div>			<div class="table-list">				<table id="guessList" class="layui-table" lay-filter="guess">				</table>			</div>	</div><link rel="stylesheet" href="{pigcms{$static_public}layui2/css/layui.css" media="all"/><script src="{pigcms{$static_public}layui2/layui.all.js" charset="utf-8"></script><style>    #main-container{        background: white !important;    }</style><script type="text/html" id="barDemo">	{{# if(d.is_related == 0){ }}	<button class="layui-btn layui-btn-xs" lay-event="related">关联</button>	{{# }else{ }}	<button class="layui-btn layui-btn-xs" lay-event="unrelated">取消关联</button>	{{# } }}</script><script>  var guessList = '{pigcms{:U('index_guess_list',array('id' => $id))}';  layui.use(['laydate','table','layer'], function(){    var table = layui.table;    var layer = layui.layer;    // 列表    table.render({      elem: '#guessList',      url: guessList,      method:'post',      toolbar: false ,      page: true ,      cols: [[ //表头        {field: 'name',width: 160,title: '商品名称'}        ,{field: 'phone',width: 140,title: '手机号'}        ,{width: 100,title: '排序',templet:function (d){            return '<input type="number" value="'+ d.sort +'" class="sort_number sort_number_'+ d.store_id +'" min="0" max="99999" />';          }}        ,{field: 'id', title: '操作',width: 95,toolbar: '#barDemo'}      ]],      id:'guessList',    });    // 操作监听    table.on('tool(guess)', function (obj){      // 审核      if(obj.event == 'related'){        layer.confirm('确定关联吗？', function(index){          related(obj.data.store_id,'add');          layer.close(index);        });      }else if(obj.event == 'unrelated'){        layer.confirm('确定取消关联吗？', function(index){          related(obj.data.store_id,'del');          layer.close(index);        });			}    });    function related (store_id,type){      var sort = $('.sort_number_'+store_id).val();      $.post("{pigcms{:U('relateStore',array('id' => $id))}" , {store_id:store_id,type:type,sort:sort} , function(data){        console.log(data)        if(data.status==1){          layer.msg(data.msg,{            icon: 2,              time: 2000 //2秒关闭（如果不配置，默认是3秒）          })        }else{          layer.msg(data.msg,{            icon: 1,            time: 2000 //2秒关闭（如果不配置，默认是3秒）          })          // table.reload('guessList', {          //   page: {          //     curr: 1 //重新从第 1 页开始          //   }          // });        }          // $('.layui-laypage-btn').click();        console.log($('.layui-laypage-btn').click())      },'JSON');		}  });</script><style>		.sort_number {        height: 26px;        width: 70px;		}    .layui-btn-xs {        height: 28px !important;		}	.related_goods {			margin: 10px 0;			padding: 10px 20px;			border: 1px dashed #CCCCCC;			background-color: #ffffff;      display: inline-block;	}  .table-list .summary {      margin: 10px 25px 5px 0 !important;      text-align: right !important;  }  .table-list .pager {      margin: 0 25px 5px 0 !important;      text-align: right !important;  }  .pager .next>a {      height: 30px;      line-height: 30px;  }  .pager .prev>a {      height: 30px;      line-height: 30px;  }	.search_div {			display: inline-block;			margin-left: 5px;			margin-bottom: 10px;	}	.layui-laypage-limits select {			height: 26px !important;	}</style><include file="Publics:footer"/>